import json
from pathlib import Path
from tools.contextual_anchor_preflight import _decode_lua_string, _decode_lua_long_bracket, _long_bracket_opening

root = Path('.')
items = json.loads((root/'.ai/task/repair-w64-20261003/NEW-TARGETS.json').read_text())

def quote_lua(value, quote):
    escapes = {'\\':'\\\\', quote:'\\'+quote, '\a':'\\a', '\b':'\\b', '\f':'\\f', '\n':'\\n', '\r':'\\r', '\t':'\\t', '\v':'\\v'}
    out=[quote]
    for ch in value:
        if ch in escapes: out.append(escapes[ch])
        elif ord(ch)<32 or ord(ch)==127: out.append(f'\\{ord(ch):03d}')
        else: out.append(ch)
    out.append(quote)
    return ''.join(out)

by_file={}
for rid,item in items.items(): by_file.setdefault(item['file'],[]).append((rid,item))
for filename, group in by_file.items():
    path=root/filename
    text=path.read_text()
    replacements=[]
    for rid,item in group:
        hits=[]; i=0
        while i<len(text):
            if text[i] in "'\"":
                start=i
                try: value,end=_decode_lua_string(text,i)
                except Exception: i+=1; continue
                if value==item['old_target']:
                    hits.append((start,end,quote_lua(item['new_target'],text[start])))
                i=end; continue
            if text[i]=='[' and _long_bracket_opening(text,i):
                start=i
                opening=_long_bracket_opening(text,i)
                value,end=_decode_lua_long_bracket(text,i)
                if value==item['old_target']:
                    content_start, closing=opening
                    close_start=end-len(closing)
                    raw_old=text[content_start:close_start]
                    initial='\r\n' if raw_old.startswith('\r\n') else ('\n' if raw_old.startswith('\n') else ('\r' if raw_old.startswith('\r') else ''))
                    raw_new=initial+item['new_target']
                    if closing in raw_new:
                        raise SystemExit(f'{rid}: new target collides with long-bracket delimiter {closing!r}')
                    hits.append((start,end,text[start:content_start]+raw_new+closing))
                i=end; continue
            i+=1
        if len(hits)!=1: raise SystemExit(f'{rid}: expected one old target, found {len(hits)}')
        replacements.append((*hits[0],rid))
    for start,end,replacement,rid in sorted(replacements, reverse=True):
        text=text[:start]+replacement+text[end:]
    path.write_text(text)
    print(f'{filename}: replaced {len(replacements)} targets')
